import ipaddress

rules = [
    {"priority": 100, "name": "AllowHTTPS", "protocol": "TCP", "port": 443, "source": "0.0.0.0/0", "access": "Allow"},
    {"priority": 110, "name": "AllowSSHAdmin", "protocol": "TCP", "port": 22, "source": "10.0.0.0/24", "access": "Allow"},
    {"priority": 200, "name": "DenySSHInternet", "protocol": "TCP", "port": 22, "source": "0.0.0.0/0", "access": "Deny"},
    {"priority": 65500, "name": "DenyAllInbound", "protocol": "Any", "port": "*", "source": "0.0.0.0/0", "access": "Deny"},
]

def matches(rule, packet):
    if rule["protocol"] != "Any" and rule["protocol"] != packet["protocol"]:
        return False
    if rule["port"] != "*" and rule["port"] != packet["port"]:
        return False
    network = ipaddress.ip_network(rule["source"])
    return ipaddress.ip_address(packet["source_ip"]) in network

def evaluate(rules, packet):
    for rule in sorted(rules, key=lambda r: r["priority"]):
        if matches(rule, packet):
            return rule["name"], rule["access"]
    return "sin_coincidencia", "Deny"

packets = [
    {"protocol": "TCP", "port": 22, "source_ip": "10.0.0.5"},
    {"protocol": "TCP", "port": 22, "source_ip": "203.0.113.9"},
    {"protocol": "TCP", "port": 443, "source_ip": "203.0.113.9"},
    {"protocol": "UDP", "port": 53, "source_ip": "203.0.113.9"},
]

for packet in packets:
    name, access = evaluate(rules, packet)
    print(f"{packet['protocol']}:{packet['port']} desde {packet['source_ip']} -> {name} ({access})")
